mapper.insert:
INSERT INTO schedule_share_permission (owner_user_id, target_type, target_id, permission_level, created_at)
VALUES (#{ownerUserId}, #{targetType}, #{targetId}, #{permissionLevel}, NOW())
ON DUPLICATE KEY UPDATE permission_level = #{permissionLevel}

mapper.select:
SELECT COUNT(1)
FROM schedule_share_permission
WHERE owner_user_id = #{ownerUserId}
  AND target_type = #{targetType}
  AND target_id = #{targetId}
  AND permission_level = #{permissionLevel}

mapper.delete:
DELETE FROM schedule_share_permission
WHERE owner_user_id = #{ownerUserId}
  AND target_type = #{targetType}
  AND target_id = #{targetId}

mapper.select:
SELECT id, owner_user_id AS ownerUserId, target_type AS targetType, target_id AS targetId,
       permission_level AS permissionLevel, created_at AS createdAt
FROM schedule_share_permission
WHERE owner_user_id = #{ownerUserId}
  AND target_type = #{targetType}
  AND target_id = #{targetId}
LIMIT 1
